UPDATE nuke_message SET pn_title='Welcome to Northern Sky', pn_date='1101052800', pn_content='Northern Sky is an amateur astronomy club for Duluth, Superior and the North Shore. We meet the fourth Tuesday of the month (September to May) at 7:00 PM and observe whenever the lake lets us. Members and the public are welcome at all of our observing nights. New to the hobby? Read the <a href="modules.php?op=modload&amp;name=FAQ&amp;file=index">FAQ</a>, then come to a meeting - you do not need a telescope to join.' WHERE pn_mid=1;
