INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (1, 1, 'dhalvorsen', 'Welcome to the new Northern Sky website', '2003-06-14 12:05:00', 'The club finally has a website of its own. The old page on the university server was three years out of date and only Lynn could update it, so we moved to a hosted account and set up PostNuke.<br /><br />Members can register an account, post comments under news stories and submit their own observing reports. If something is broken, post a comment here or catch me at the next meeting.', '', 3, 341, 1, 'dhalvorsen', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (1, 0, 1, '2003-06-16 20:52:00', 'lynn_s', '', '', '10.3.116.4', 'Thank you!', 'Great job Dave. No more FTP for me.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (2, 0, 1, '2003-06-20 22:11:00', 'mbergstrom', '', '', '10.4.20.125', 'Looks good', 'Can we get the Clear Sky Clock on the front page?', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (3, 2, 1, '2003-06-21 08:03:00', 'dhalvorsen', '', '', '10.2.54.119', 'Re: Looks good', 'It\'s in Web Links for now. A block for it is on the list.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (2, 1, 'lynn_s', 'Mars Night at Chester Bowl draws a crowd', '2003-08-28 08:30:00', 'Last night, the night of Mars\' closest approach in 60,000 years, we set up eight telescopes in the Chester Bowl parking lot. By our count about 400 people came through between 9:30 and midnight. The line for Mark\'s 12.5-inch was still 30 people deep at 11:45.<br /><br />Mars cleared the trees around 10:30 and the seeing settled down enough to show the south polar cap and Syrtis Major. Thanks to everyone who brought a scope, and to the Parks department for leaving the lights off.', 'Several people asked how to join. Meetings resume in September, fourth Tuesday of the month. Dues are $20 a year, $10 for students.<br /><br />Mars stays well placed through September and October if you missed it.', 2, 612, 3, 'lynn_s', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (4, 0, 2, '2003-08-28 12:40:00', 'mbergstrom', '', '', '10.4.166.111', 'Sore feet', 'I think I said "that white spot at the bottom is the polar cap" about 300 times. Worth it.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (5, 0, 2, '2003-08-29 09:20:00', 'rtorgerson', '', '', '10.6.25.61', 'First time visitor', 'I was one of the 400. Joined this morning. My old Unitron 60mm is coming out of the closet.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (3, 3, 'dhalvorsen', 'Comet NEAT finally clears the trees', '2004-05-17 22:58:00', 'Jeff writes: "After a week of clouds I finally got Comet NEAT (C/2001 Q4) from the hill behind my house on Saturday. It was an easy naked-eye fuzzy star about 15 degrees up in the west, sitting just above the Beehive cluster. In 10x50s the tail was about two degrees long."<br /><br />NEAT is fading and moving north, so the next week is the best chance. Comet LINEAR (C/2002 T7) is a morning object and very low from here.', '', 2, 288, 4, 'skyguy_mn', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (6, 0, 3, '2004-05-18 07:15:00', 'gwilson', '', '', '10.9.115.244', 'Saw it too', 'From Proctor at 10:15. Beehive and comet in the same binocular field.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (7, 0, 3, '2004-05-18 21:40:00', 'katie_p', '', '', '10.7.212.87', 'Picture', 'Got a 30 second shot with the 300D on a tripod. Will post it at the meeting.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (4, 2, 'lynn_s', 'Transit of Venus at sunrise from Brighton Beach', '2004-06-09 07:10:00', 'Nine of us were at Brighton Beach by 4:45 yesterday morning to catch the end of the transit of Venus. The Sun came up out of the lake at 5:17 with Venus already close to its edge, a sharp black dot that was visible through the eclipse glasses even with the Sun that low.<br /><br />Third contact came at 6:04 and Venus was off the disk at about 6:23. Rick\'s Unitron with a Baader film filter gave the best view. Dave got the black drop effect on his webcam, but only just.', 'Nobody alive has seen one before 2004, and the next is June 2012. From Duluth the 2012 transit happens in the late afternoon, so we will see the whole first half of it.<br /><br />Thanks to the sixty or so early risers who stopped on their way to work.', 3, 455, 6, 'lynn_s', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (8, 0, 4, '2004-06-09 08:30:00', 'rtorgerson', '', '', '10.6.103.249', 'Worth getting up for', 'Saw it from the beach with my wife. Venus looked bigger than I expected.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (9, 0, 4, '2004-06-09 12:02:00', 'dobfan10', '', '', '10.10.237.211', 'Glad I came', 'Saw the sign on the road and pulled over. I have an XT10 at home and never knew there was a club. Registered.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (10, 0, 4, '2004-06-09 18:45:00', 'dhalvorsen', '', '', '10.2.30.67', 'Webcam frames', 'Ten frames of the black drop are up in the forum. The seeing over the lake was bad.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (5, 3, 'dhalvorsen', 'Supernova 2004dj in NGC 2403 - seen from Hermantown', '2004-08-03 09:30:00', 'Jeff writes: "Koichi Itagaki found a supernova in NGC 2403 in Camelopardalis on July 31. It is about magnitude 11.5, one of the brightest in years. NGC 2403 is circumpolar from here, so I got up at 3:30 Monday morning when it is higher in the northeast."<br /><br />"At 120x in the 10-inch the supernova is an obvious star at the east edge of the galaxy\'s bright central region. No mistaking it once you have looked at a picture of the galaxy beforehand."', 'The galaxy is 11 to 12 million light years away. Charts are on the AAVSO website for anyone who wants to estimate magnitudes. It should stay above 13th magnitude for a few weeks.', 2, 297, 5, 'skyguy_mn', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (11, 0, 5, '2004-08-03 22:10:00', 'mbergstrom', '', '', '10.4.31.202', 'Confirmed from Superior', 'Got it at 4 AM with the 12.5. Easy. First supernova for me.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (12, 0, 5, '2004-08-05 06:55:00', 'skyguy_mn', '', '', '10.5.241.1', 'Estimate', '11.3 this morning against the AAVSO sequence.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (6, 2, 'lynn_s', 'Total lunar eclipse: clear skies over Leif Erikson Park', '2004-10-28 07:45:00', 'For once the weather cooperated. The clouds broke up around 8 PM and we had a clear sky for the whole total eclipse last night, which ran from 9:23 to 10:45. Seven club telescopes were set up in Leif Erikson Park and we had around 150 visitors, plus a few dozen more who watched from the Lakewalk.<br /><br />The Moon went a coppery orange with a brighter lower edge. Saturn was rising in the east during totality and Mark swung over to it for the people who asked what that bright star was.', 'There is no total lunar eclipse visible from here again until March 2007.', 3, 516, 6, 'lynn_s', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (13, 0, 6, '2004-10-28 08:51:00', 'ellie_k', '', '', '10.11.146.68', 'Thank you', 'I was the one in the purple hat asking all the questions. My first time looking through a telescope. I have joined the site and will be at the next meeting.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (14, 13, 6, '2004-10-28 09:30:00', 'lynn_s', '', '', '10.3.42.103', 'Re: Thank you', 'Welcome Ellen! Bring the binoculars too.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (15, 0, 6, '2004-10-28 12:15:00', 'gwilson', '', '', '10.9.64.9', 'Red Sox', 'Same night the Red Sox won the Series. Good night for long waits finally ending.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (7, 1, 'dhalvorsen', 'Site upgraded to PostNuke .750, new forums', '2004-11-21 10:00:00', 'The site is now running PostNuke .750. The old theme did not survive the upgrade, so we are on the plain default theme for now. It loads faster on dial-up anyway.<br /><br />The forums have moved to PNphpBB2. Your site login works in the forums, there is no separate registration. Old forum posts are archived and not imported, sorry.', '', 1, 233, 1, 'dhalvorsen', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (16, 0, 7, '2004-11-21 14:30:00', 'nate_astro', '', '', '10.8.17.228', 'Forums', 'The forums look much better. Quick reply works.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (8, 3, 'dhalvorsen', 'Geminids: 70 an hour before the clouds', '2004-12-14 08:20:00', 'Gary writes: "Four of us were at the Rice Lake Road field from 10 PM to 1:30 AM on the peak night. With no Moon and minus 4 degrees we counted 70 an hour at the best, including two that lit up the snow. Clouds came in off the lake at 1:30 and that was that."', '', 1, 198, 4, 'gwilson', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (17, 0, 8, '2004-12-14 12:00:00', 'superior_sky', '', '', '10.12.123.243', 'Missed it', 'Overcast in Superior all night. Next year.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (9, 1, 'lynn_s', 'Holiday potluck and 2005 officers', '2004-12-20 16:00:00', 'Thanks to the 31 members and family who came to the holiday potluck. Officers for 2005: Lynn Sorensen, president; Mark Bergstrom, vice president and observing chair; Carol Mattson has agreed to take over outreach scheduling; Gary Wilson stays as treasurer; Dave Halvorsen stays webmaster.<br /><br />Dues for 2005 are due at the January meeting. Still $20, $10 for students.', '', 0, 176, 2, 'lynn_s', '', 0, '', '', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (10, 3, 'dhalvorsen', 'Comet Machholz meets the Pleiades', '2005-01-09 21:40:00', 'Katie writes: "Comet Machholz (C/2004 Q2) passed the Pleiades on Friday and Saturday. I got out to the Rice Lake Road field Saturday night with the 300D on Nate\'s mount. The comet was naked eye at about magnitude 3.5, a green fuzzy spot a few degrees from the cluster. 20 x 30 second exposures stacked show the thin blue ion tail."<br /><br />The comet is now heading north through Perseus and stays up all night. Charts are in Downloads.', '', 4, 402, 4, 'katie_p', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (18, 0, 10, '2005-01-10 07:30:00', 'mbergstrom', '', '', '10.4.42.194', 'Nice', 'Saw your picture on the forum. That ion tail is great.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (19, 0, 10, '2005-01-10 19:25:00', 'ellie_k', '', '', '10.11.116.11', 'Naked eye', 'Found it with no binoculars from my driveway in Esko. Very proud of myself.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (20, 0, 10, '2005-01-11 15:20:00', 'cmattson', '', '', '10.13.30.104', 'Library display', 'Katie, could we print your picture for the display case at the library?', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (21, 20, 10, '2005-01-11 21:02:00', 'katie_p', '', '', '10.7.183.80', 'Re: Library display', 'Of course. I will bring a print to the meeting.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (11, 2, 'lynn_s', 'Saturn at opposition tonight', '2005-01-13 17:00:00', 'Saturn is at opposition today, rising at sunset and up all night in Gemini. It is about as bright as it gets, magnitude -0.4, and the rings are tilted wide open. Any telescope will show the rings and Titan.<br /><br />Tomorrow the Huygens probe lands on Titan. It would be nice to look at Titan tonight and know there is a spacecraft on the way down to it.', '', 1, 264, 3, 'lynn_s', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (22, 0, 11, '2005-01-14 08:10:00', 'dhalvorsen', '', '', '10.2.8.82', 'Seeing', 'Seeing was very good after midnight. Cassini division all the way around.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (12, 1, 'lynn_s', 'Lakeview Elementary star night: 140 kids and one cold Saturn', '2005-02-12 11:30:00', 'Carol writes: "Thursday\'s star night at Lakeview Elementary was our biggest school event yet. About 140 students and parents came out at 6:30 to the school field at 2 degrees above zero. Six telescopes were on Saturn, the Orion Nebula, the Pleiades and the thin crescent Moon low in the west."<br /><br />"Inside, Rick ran the slide show on the gym wall and Nate brought a mirror blank so the kids could see how a telescope mirror starts out. Thank you to all the volunteers. The school has asked us back in May."', '', 3, 187, 7, 'cmattson', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (23, 0, 12, '2005-02-12 14:05:00', 'rtorgerson', '', '', '10.6.246.1', 'Fun night', 'One girl asked if Saturn was a sticker on the lens. Best question of the night.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (24, 0, 12, '2005-02-12 20:40:00', 'nate_astro', '', '', '10.8.128.141', 'Mirror blank', 'The mirror blank got more questions than Saturn did. Next time I bring the grinding stroke demo.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (25, 0, 12, '2005-02-13 10:02:00', 'lynn_s', '', '', '10.3.90.219', 'Thank you', 'Thanks Carol for organizing. We have three more schools asking.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (13, 1, 'lynn_s', 'February meeting: Cassini-Huygens at Saturn', '2005-02-14 19:00:00', 'The February meeting is Tuesday the 22nd at 7:00 PM. Katie Paquette will talk about the Huygens landing on Titan and the first pictures from the surface. Mark has the "what\'s up" for March, including the Messier Marathon.<br /><br />Same room as always unless the forum says otherwise. Bring a friend.', '', 0, 96, 2, 'lynn_s', '', 0, '', '', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (14, 1, 'dhalvorsen', 'Loaner telescopes back in circulation', '2005-02-16 20:15:00', 'Mark writes: "The club\'s two loaner telescopes are back from repair and available for members to borrow for a month at a time. The Orion XT8 Dobsonian has a new focuser and the Meade ETX-90 has new batteries and a fixed declination clutch."<br /><br />"Sign-out is at the meetings. You need to have been a member for 30 days. The loaner agreement is in Downloads."', '', 2, 81, 8, 'mbergstrom', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (26, 0, 14, '2005-02-17 21:45:00', 'ben_r', '', '', '10.14.214.205', 'Question', 'Can I borrow the XT8 if I just joined? I have an old department store scope and want to compare.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (27, 26, 14, '2005-02-18 06:50:00', 'mbergstrom', '', '', '10.4.227.69', 'Re: Question', 'After 30 days, yes. Come to the meeting anyway and look through mine.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (15, 2, 'lynn_s', 'Messier Marathon: March 11 at Rice Lake Road', '2005-02-18 21:30:00', 'Mark writes: "New Moon is March 10, so the Messier Marathon is Friday March 11 at the Rice Lake Road field, with Saturday March 12 as the rain date. From our latitude you cannot get all 110. The low objects in Sagittarius come up too close to dawn. A hundred is a very good night."<br /><br />"Start at sunset with M77 and M74 low in the west and finish around 5:30 AM. Dress for 10 below. The checklist in marathon order is in Downloads."', '', 3, 74, 5, 'mbergstrom', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (28, 0, 15, '2005-02-19 08:40:00', 'dobfan10', '', '', '10.10.98.20', 'Count me in', 'I\'ll be there with the XT10. Last year I got 87.', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (29, 0, 15, '2005-02-19 11:15:00', 'superior_sky', '', '', '10.12.167.122', 'Binoculars?', 'Has anyone tried it with only binoculars?', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (30, 29, 15, '2005-02-19 13:20:00', 'skyguy_mn', '', '', '10.5.30.207', 'Re: Binoculars?', 'Some people get 70 or more with 15x70s. The globulars are the hard part.', 0, 0);
INSERT INTO nuke_stories (pn_sid, pn_catid, pn_aid, pn_title, pn_time, pn_hometext, pn_bodytext, pn_comments, pn_counter, pn_topic, pn_informant, pn_notes, pn_ihome, pn_themeoverride, pn_language, pn_withcomm, pn_format_type) VALUES (16, 1, 'dhalvorsen', 'Rice Lake Road field is plowed for tonight', '2005-02-20 09:15:00', 'Mark writes: "The Clear Sky Clock has tonight dark blue from 8 PM on. The field is plowed and I will be there from about 7:30. Saturn, M42, and if anyone wants to stay late, galaxies in Leo."', '', 1, 38, 2, 'mbergstrom', '', 0, '', '', 0, 0);
INSERT INTO nuke_comments (pn_tid, pn_pid, pn_sid, pn_date, pn_name, pn_email, pn_url, pn_host_name, pn_subject, pn_comment, pn_score, pn_reason) VALUES (31, 0, 16, '2005-02-20 10:30:00', 'ellie_k', '', '', '10.11.90.115', 'I\'ll come', 'I\'ll come by after supper with the binoculars.', 0, 0);
