INSERT INTO nuke_faqcategories (pn_id_cat, pn_categories, pn_language, pn_parent_id) VALUES (1, 'Joining the club', '', 0);
INSERT INTO nuke_faqcategories (pn_id_cat, pn_categories, pn_language, pn_parent_id) VALUES (2, 'Getting started in astronomy', '', 0);
INSERT INTO nuke_faqanswer (pn_id, pn_id_cat, pn_question, pn_answer, pn_submittedby) VALUES (1, 1, 'When and where are meetings?', 'Fourth Tuesday of the month, September through May, 7:00 PM. Visitors are always welcome.', 'lynn_s');
INSERT INTO nuke_faqanswer (pn_id, pn_id_cat, pn_question, pn_answer, pn_submittedby) VALUES (2, 1, 'How much are dues?', '$20 a year, $10 for students. Dues are collected at the January meeting.', 'lynn_s');
INSERT INTO nuke_faqanswer (pn_id, pn_id_cat, pn_question, pn_answer, pn_submittedby) VALUES (3, 1, 'Do I need a telescope to join?', 'No. About a third of our members started with binoculars or nothing at all. Members can borrow one of the club loaner telescopes after 30 days.', 'lynn_s');
INSERT INTO nuke_faqanswer (pn_id, pn_id_cat, pn_question, pn_answer, pn_submittedby) VALUES (4, 2, 'What telescope should I buy?', 'Come to an observing night and look through several first. For most people a 6 or 8 inch Dobsonian is the best value. Avoid anything sold by magnification.', 'lynn_s');
INSERT INTO nuke_faqanswer (pn_id, pn_id_cat, pn_question, pn_answer, pn_submittedby) VALUES (5, 2, 'Where do you observe?', 'Our dark site is a field off Rice Lake Road north of town. Public nights are in town at Leif Erikson Park or Chester Bowl. Check the news page before driving out.', 'lynn_s');
INSERT INTO nuke_faqanswer (pn_id, pn_id_cat, pn_question, pn_answer, pn_submittedby) VALUES (6, 2, 'How cold does it get?', 'Minus 20 is not unusual in January. Dress in layers, wear boots rated for the cold, and bring a thermos. The forums have a thread on this.', 'lynn_s');
INSERT INTO nuke_reviews (pn_id, pn_date, pn_title, pn_text, pn_reviewer, pn_email, pn_score, pn_cover, pn_url, pn_url_title, pn_hits, pn_language) VALUES (1, '2004-07-12 21:00:00', 'Orion SkyQuest XT8 Dobsonian', 'The club bought an XT8 for the loaner program last spring and it has been out nearly every month since. The optics are good, with a clean star test on our copy. It sets up in two minutes and holds collimation well after a car ride.<br /><br />Downsides: the stock focuser is rack and pinion and a bit rough, and the base is heavy for some people. In the cold the bearings stiffen up. For a first serious telescope at around $400 it is hard to beat.', 'mbergstrom', 'mbergstrom@northernsky.example', 9, '', '', '', 168, '');
INSERT INTO nuke_reviews (pn_id, pn_date, pn_title, pn_text, pn_reviewer, pn_email, pn_score, pn_cover, pn_url, pn_url_title, pn_hits, pn_language) VALUES (2, '2004-09-20 20:30:00', 'Coronado PST solar telescope', 'A hydrogen-alpha telescope for $499 was unthinkable two years ago. The PST shows prominences on the limb and filaments on the disk right away, and kids at outreach events love it.<br /><br />It is a 40mm aperture, so the image is small, and the tuning ring takes some practice. Use a good eyepiece, not the one in the box. Worth it.', 'dhalvorsen', 'dhalvorsen@northernsky.example', 8, '', '', '', 161, '');
