INSERT INTO nuke_phpbb_posts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (4, '', 'Machholz from Esko, Jan 8', 'Found Comet Machholz with no help tonight! It was right where the chart said, to the right of the Pleiades. Looked like a fuzzy star in the 10x50s, a bit green maybe.');
INSERT INTO nuke_phpbb_posts (post_id, topic_id, forum_id, poster_id, post_time, poster_ip, post_username, enable_bbcode, enable_html, enable_smilies, enable_sig, post_edit_time, post_edit_count, post_attachment, post_icon) VALUES (5, 2, 2, 5, 1105280100, '0a059d3b', '', 1, 0, 1, 1, NULL, 0, 0, 0);
INSERT INTO nuke_phpbb_posts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (5, '', '', 'Nice work. It is about magnitude 3.5 so naked eye from a dark spot. Look for a very faint tail going up and to the left.');
