INSERT INTO nuke_phpbb_posts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (6, '', '', 'Was at Rice Lake Road tonight. The ion tail shows up in 30 second exposures. Will post when I get it stacked.');
