INSERT INTO nuke_phpbb_posts_text (post_id, bbcode_uid, post_subject, post_text) VALUES (8, '', 'Saturn on opposition night', 'Seeing was 8 out of 10 after midnight. Cassini division all the way around and the Crepe ring across the planet. Five moons in the 8 inch.');
